import AppKit

/// The official Ace Hardware logo (two-line, full color) from the store's
/// retailer brand kit, embedded as a PNG so the app needs no external
/// resource files. A custom logo chosen in Settings overrides it; the drawn
/// badge in AceBadgeView is the last-resort fallback. The vector originals
/// live in AceSignStudio/BrandAssets/.
enum AceBrand {
    static let logo: NSImage? = {
        guard let data = Data(base64Encoded: logoBase64) else { return nil }
        return NSImage(data: data)
    }()

    private static let logoBase64 = ""
}
